      "summary": "무릎 소리만으로 손상을 판단할 수는 없습니다. 통증·붓기·움직임 제한이 없고 일상에 불편이 없다면 변화를 관찰할 수 있습니다. 새 증상이나 잠김, 외상 뒤 심한 증상이 있으면 진료를 고려하세요. 제공된 자료만으로는 당일 진료와 응급 진료의 경계를 확정할 수 없습니다.",
